const store = $getWorkflowStaticData('global');
const errCache = store.errDetails || {};
const userCache = store.userDetails || {};
const ids = ['RDvqE9FfPL7UVHLM', 'MoNX5kmPN1uaZnY9', 'LbxcSlq28pX0uFpr'];
const TELEGRAM = 'MoNX5kmPN1uaZnY9';
const MAX = 25;
const execs = $input.all().map(i => i.json)
  .filter(e => e && e.id && ids.includes(String(e.workflowId)) && e.mode !== 'manual' && (e.status === 'success' || e.status === 'error' || e.status === 'crashed'))
