execs.filter(e => e.status !== 'success')
  .forEach(e => { if (!errCache[String(e.id)]) want.add(String(e.id)); });
return Array.from(want).slice(0, MAX).map(id => ({ json: { id } }));

// ================== CONFIGURACIÓN ==================
// Servicios fuera de línea A PROPÓSITO (pre-producción).
// Cuando un servicio pase a producción, quitá su nombre de esta lista.
const SERVICIOS_PAUSADOS = ['JeriGo - Ingesta SharePoint'];
const TEXTO_PAUSADO = 'Pausado hasta el pase a producción';
const N8N_URL = 'https://n8nadminjs.app.n8n.cloud';
// Registro opcional en el historial para los servicios pausados: fecha FIJA (hora de Buenos Aires).
// Dejalo vacío ('') para no mostrar ninguna fila de "Pausado" en el historial.
const PAUSADO_DESDE = '';
// Traducción de ID de Telegram -> nombre real (tiene prioridad sobre el nombre de Telegram)
const USUARIOS = {
  // '123456789': 'Nombre Apellido',
};
const SERVICIO_TELEGRAM = 'MoNX5kmPN1uaZnY9'; // Chat WhatsApp
const NODO_TRIGGER = 'Telegram Trigger';
const LOGO_URL = 'https://jerarquicos.com/wp-content/uploads/2024/01/jerarquicos-logo.svg';
const REFRESCO_SEG = 20;
// Nombres a MOSTRAR en pantalla (nombre real del workflow en n8n -> nombre visible).
// La lógica sigue usando el ID y el nombre real; esto solo cambia lo que se ve.
const NOMBRES_VISIBLES = {
  'JeriGo - Chat WhatsApp': 'JeriGO - Chat WhatsApp',
  'JeriGo - Monitoreo de errores': 'JeriGO - Monitoreo de errores',
  'JeriGo - Ingesta SharePoint': 'JeriGO - Ingesta SharePoint'
};
// ===================================================

const TZ = 'America/Buenos_Aires';
const now = Date.now();
const H1 = 3600 * 1000;
const H24 = 24 * H1;

const WANTED = [
  { id: 'RDvqE9FfPL7UVHLM', name: 'JeriGo - Ingesta SharePoint' },
  { id: 'MoNX5kmPN1uaZnY9', name: 'JeriGo - Chat WhatsApp' },
  { id: 'LbxcSlq28pX0uFpr', name: 'JeriGo - Monitoreo de errores' }
];
const wantedIds = WANTED.map(w => w.id);
const publishedIds = $('Obtener workflows').all().map(i => i.json).filter(w => w && w.id && (w.active || w.activeVersionId)).map(w => w.id);
function nombreVisible(real) {
  const k = Object.keys(NOMBRES_VISIBLES).find(n => n.trim().toLowerCase() === String(real).trim().toLowerCase());
  return k ? NOMBRES_VISIBLES[k] : String(real).replace(/^jerigo\b/i, 'JeriGO');
}
const workflows = WANTED.map(w => ({ id: w.id, name: w.name, label: nombreVisible(w.name), active: publishedIds.includes(w.id) }));
const executions = $('Obtener ejecuciones').all().map(i => i.json).filter(e => e && e.id && wantedIds.includes(String(e.workflowId)));

const pausedNames = SERVICIOS_PAUSADOS.map(n => String(n).trim().toLowerCase());
function isPausedName(name) { return pausedNames.includes(String(name).trim().toLowerCase()); }

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
// Formato consistente dd/mm HH:mm (24 h, hora de Buenos Aires)
const dtf = new Intl.DateTimeFormat('es-AR', { timeZone: TZ, day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
function fmt(d) {
  if (!d) return '-';
  const p = {};
  dtf.formatToParts(new Date(d)).forEach(x => { p[x.type] = x.value; });
  const z = v => String(v).padStart(2, '0');
  return z(p.day) + '/' + z(p.month) + ' ' + z(p.hour === '24' ? '00' : p.hour) + ':' + z(p.minute);
}
function ago(d) {
  if (!d) return 'sin datos';
  const m = Math.round((now - new Date(d).getTime()) / 60000);
  if (m < 1) return 'recién';
  if (m < 60) return 'hace ' + m + ' min';
  const h = Math.round(m / 60);
  if (h < 48) return 'hace ' + h + ' h';
  return 'hace ' + Math.round(h / 24) + ' d';
}
function isFail(s) { return s === 'error' || s === 'crashed'; }
// Las ejecuciones manuales son pruebas: no cuentan para la disponibilidad
function isProd(e) { return e.mode !== 'manual'; }

const byWf = {};
for (const w of workflows) {
  byWf[w.id] = { id: w.id, name: w.name, label: w.label, active: w.active, total24: 0, ok24: 0, okMs24: 0, okN24: 0, lastProd: null, lastOk: null };
}
for (const e of executions) {
  const s = byWf[e.workflowId];
  if (!s || !isProd(e)) continue;
  const t = new Date(e.startedAt || e.createdAt || 0).getTime();
  if (e.status === 'running' || e.status === 'waiting') continue; // sin resultado final todavía
  if (!s.lastProd || t > new Date(s.lastProd.startedAt || 0).getTime()) s.lastProd = e;
  if (e.status === 'success' && (!s.lastOk || t > new Date(s.lastOk.startedAt || 0).getTime())) s.lastOk = e;
  if (now - t <= H24) {
    s.total24++;
    if (e.status === 'success') {
      s.ok24++;
      const ms = new Date(e.stoppedAt || 0).getTime() - t;
      if (t && ms >= 0) { s.okMs24 += ms; s.okN24++; }
    }
  }
}

const list = workflows.map(w => byWf[w.id]).map(s => {
  if (!s.active && isPausedName(s.name)) { s.level = 'paused'; s.status = 'PAUSADO'; s.detail = TEXTO_PAUSADO; }
  else if (!s.active) { s.level = 'red'; s.status = 'FUERA DE LÍNEA'; s.detail = 'El workflow no está publicado'; }
  else if (s.lastProd && isFail(s.lastProd.status)) { s.level = 'red'; s.status = 'CAÍDO'; s.detail = 'Falló su última ejecución real (' + ago(s.lastProd.startedAt) + ')'; }
  else { s.level = 'green'; s.status = 'EN LÍNEA'; s.detail = 'Publicado y respondiendo'; }
  return s;
});
const order = { green: 0, red: 1, paused: 2 };
list.sort((a, b) => order[a.level] - order[b.level]);

const down = list.filter(s => s.level === 'red');
const paused = list.filter(s => s.level === 'paused');
const up = list.filter(s => s.level === 'green').length;
const tot24 = list.reduce((a, s) => a + s.total24, 0);
const ok24 = list.reduce((a, s) => a + s.ok24, 0);
// Tasa de éxito 24 h (solo ejecuciones reales). Se muestra truncada para que coincida con los umbrales.
const tasa = tot24 ? ok24 * 100 / tot24 : null;
const tasaTxt = tasa === null ? '-' : Math.floor(tasa) + ' %';
const tasaCls = tasa === null ? '' : (tasa >= 95 ? ' g' : (tasa >= 80 ? ' a' : ' r'));
function promedio(s) { return s.okN24 ? (s.okMs24 / s.okN24 / 1000).toFixed(1).replace('.', ',') + ' s' : '-'; }
const global = down.length ? 'red' : 'green';
const globalText = down.length
  ? (down.length === 1 ? '1 servicio caído: ' : down.length + ' servicios caídos: ') + down.map(s => esc(s.label)).join(', ')
  : 'Todos los servicios activos operan con normalidad';
const globalNote = paused.length ? (paused.length === 1 ? '1 servicio pausado' : paused.length + ' servicios pausados') : '';

// Línea de tiempo de disponibilidad: caídas y recuperaciones (solo ejecuciones reales)
function dur(ms) {
  const m = Math.max(1, Math.round(ms / 60000));
  if (m < 60) return m + ' min';
  const h = Math.floor(m / 60);
  if (h < 48) return h + ' h ' + (m % 60) + ' min';
  return Math.floor(h / 24) + ' d ' + (h % 24) + ' h';
}
// Detalle de errores: solo nodo que falló + mensaje resumido y sin contenido de conversación.
// Se guarda en memoria del workflow para consultar cada ejecución fallida una sola vez.
function cleanErr(msg) {
  let t = String(msg || '').split('\n')[0];
  t = t.replace(/"[^"]*"|'[^']*'|“[^”]*”|«[^»]*»/g, '"…"');
  t = t.replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '[email]');
  t = t.replace(/\+?\d[\d\s.-]{5,}\d/g, '[número]');
  t = t.replace(/\{.*\}|\[.*\]/g, '{…}');
  if (t.length > 110) t = t.slice(0, 107) + '…';
  return t || 'Error sin detalle';
}
const store = $getWorkflowStaticData('global');
const errCache = store.errDetails || {};
const userCache = store.userDetails || {};
// Solo se toman nombre, usuario e ID del remitente; nunca el texto del mensaje
function pickUser(rd) {
  const run = rd && rd.runData ? rd.runData : {};
  const keys = run[NODO_TRIGGER] ? [NODO_TRIGGER] : Object.keys(run);
  for (const k of keys) {
    try {
      const j = run[k][0].data.main[0][0].json;
      const f = (j.message && j.message.from) || (j.callback_query && j.callback_query.from) || (j.edited_message && j.edited_message.from);
      if (f && f.id) return { id: String(f.id), first: String(f.first_name || '').slice(0, 40), last: String(f.last_name || '').slice(0, 40), username: String(f.username || '').slice(0, 40) };
    } catch (e) { /* sin datos de este nodo */ }
  }
  return null;
}
let detalles = [];
try { detalles = $('Detalle de ejecuciones').all().map(i => i.json); } catch (e) { detalles = []; }
for (const d of detalles) {
  if (!d || !d.id || !d.data) continue;
  if (String(d.workflowId) === SERVICIO_TELEGRAM) userCache[String(d.id)] = pickUser(d.data.resultData) || { none: true };
  if (d.status !== 'error' && d.status !== 'crashed') continue;
  const rd = (d.data && d.data.resultData) || {};
  const er = rd.error || {};
  let nodeName = (er.node && er.node.name) || rd.lastNodeExecuted || '';
  let msg = er.message || er.description || '';
  if (!msg && rd.runData) {
    for (const k of Object.keys(rd.runData)) {
      const runs = rd.runData[k] || [];
      const bad = runs.find(r => r && r.error);
      if (bad) { nodeName = nodeName || k; msg = bad.error.message || ''; break; }
    }
  }
  errCache[String(d.id)] = { node: String(nodeName || '').slice(0, 60), msg: cleanErr(msg) };
}
const liveIds = new Set(executions.map(e => String(e.id)));
for (const k of Object.keys(errCache)) if (!liveIds.has(k)) delete errCache[k];
for (const k of Object.keys(userCache)) if (!liveIds.has(k)) delete userCache[k];
store.errDetails = errCache;
store.userDetails = userCache;
function userText(id) {
  const u = userCache[String(id)];
  if (!u || u.none || !u.id) return '';
  const name = USUARIOS[u.id] || [u.first, u.last].filter(Boolean).join(' ');
  if (name) return name + (u.username ? ' (@' + u.username + ')' : '') + ' · ID ' + u.id;
  return u.username ? '@' + u.username : 'ID ' + u.id;
}
function userSearch(id) {
  const u = userCache[String(id)];
  if (!u || u.none || !u.id) return '';
  return [USUARIOS[u.id] || '', u.first, u.last, u.username, '@' + u.username, u.id].join(' ').toLowerCase();
}

function durExec(e) {
  const a = new Date(e.startedAt).getTime(), b = new Date(e.stoppedAt || 0).getTime();
  if (!a || !b || b < a) return '-';
  const ms = b - a;
  if (ms < 60000) return (ms / 1000).toFixed(1).replace('.', ',') + ' s';
  return Math.floor(ms / 60000) + ' min ' + Math.round((ms % 60000) / 1000) + ' s';
}
const STATUS_TXT = { success: 'Exitosa', error: 'Error', crashed: 'Falla grave' };

const events = [];
for (const w of workflows) {
  const runs = executions
    .filter(e => String(e.workflowId) === w.id && isProd(e) && (e.status === 'success' || isFail(e.status)))
    .sort((a, b) => new Date(a.startedAt) - new Date(b.startedAt));
  let downSince = null;
  for (const e of runs) {
    // Ejecuciones reales (solo metadatos)
    if (e.status === 'success') {
      const ut = userText(e.id);
      events.push({ t: e.startedAt, wf: w.id, name: w.label, cat: 'exec', type: 'ok', text: 'Ejecución OK', detail: ut || ('Origen: ' + (e.mode || '-')), user: userSearch(e.id), dur: durExec(e), id: e.id, st: STATUS_TXT.success, err: 0 });
    } else {
      const d = errCache[String(e.id)];
      const errTxt = d ? ((d.node ? 'Nodo «' + d.node + '»: ' : '') + d.msg) : 'Detalle del error no disponible';
      const ut = userText(e.id);
      const det = ut ? ut + ' · ' + errTxt : errTxt;
      events.push({ t: e.startedAt, wf: w.id, name: w.label, cat: 'exec', type: 'err', text: 'Ejecución con error', detail: det, user: userSearch(e.id), dur: durExec(e), id: e.id, st: STATUS_TXT[e.status] || 'Error', err: 1 });
    }
    // Disponibilidad
    if (isFail(e.status) && !downSince) {
