      events.push({ t: e.startedAt, wf: w.id, name: w.label, cat: 'avail', type: 'down', text: 'Se cayó', detail: 'Falló una ejecución real (' + (e.mode || '') + ')', dur: '-', id: e.id, st: 'Caído', err: 1, seq: 1 });
    } else if (e.status === 'success' && downSince) {
