  for (const s of list) {
    if (s.level === 'paused') events.push({ t: pausadoT.toISOString(), wf: s.id, name: s.label, cat: 'avail', type: 'paused', text: 'Pausado', detail: TEXTO_PAUSADO, dur: '-', id: '', st: 'Pausado', err: 0 });
  }
}
// Orden único por fecha real (más reciente primero); desempate estable por ID de ejecución
events.sort((a, b) => (new Date(b.t) - new Date(a.t)) || ((Number(b.id) || 0) - (Number(a.id) || 0)) || ((b.seq || 0) - (a.seq || 0)));
