// Refresco por JS: misma URL (mismo origen, el navegador reenvía el login), timeout de 15 s,
// reintento silencioso ante un fallo aislado y aviso recién al segundo fallo seguido.
const script = '<script>(function(){' +
  'var TZ="' + TZ + '",INT=' + (REFRESCO_SEG * 1000) + ',TO=15000,lastOk=Date.now(),fails=0,busy=false,timer=null;' +
  'var F={cat:"all",svc:"all",q:"",shown:50};' +
  'function rel(ms){var s=Math.max(0,Math.floor(ms/1000));if(s<60)return "hace "+s+" s";var m=Math.floor(s/60);if(m<60)return "hace "+m+" min";return "hace "+Math.floor(m/60)+" h "+(m%60)+" min";}' +
  'function tick(){var c=document.getElementById("clk");if(c)c.textContent=new Date().toLocaleTimeString("es-AR",{timeZone:TZ,hourCycle:"h23"});' +
    'var s=document.getElementById("since");if(s)s.textContent="última actualización exitosa "+rel(Date.now()-lastOk);' +
    'var r=document.getElementById("rs");if(r){var bad=fails>=2;r.className=bad?"rs err":"rs";r.textContent=bad?"Sin conexión con el servidor · reintentando":"Conectado · refresco cada "+(INT/1000)+" s";}}' +
  'function apply(){var rows=document.querySelectorAll("#hist tbody tr[data-cat]"),tot=0,vis=0;' +
    'for(var i=0;i<rows.length;i++){var r=rows[i],c=r.getAttribute("data-cat");' +
      'var ok=(F.cat==="all"||(F.cat==="err"?r.getAttribute("data-err")==="1":c===F.cat))&&(F.svc==="all"||r.getAttribute("data-svc")===F.svc)&&(!F.q||(r.getAttribute("data-user")||"").indexOf(F.q)>=0);' +
      'if(ok){tot++;if(tot<=F.shown){vis++;r.style.display="";}else r.style.display="none";}else r.style.display="none";}' +
    'var e=document.querySelector("#hist tr.empty");if(e)e.style.display=tot?"none":"";' +
    'var m=document.getElementById("more");if(m)m.style.display=tot>F.shown?"":"none";' +
    'var n=document.getElementById("cnt");if(n)n.textContent=tot?("Mostrando "+vis+" de "+tot):"";' +
    'var bs=document.querySelectorAll("[data-f]");for(var j=0;j<bs.length;j++)bs[j].className=bs[j].getAttribute("data-f")===F.cat?"on":"";' +
    'var sel=document.getElementById("svcSel");if(sel)sel.value=F.svc;var q=document.getElementById("userQ");if(q&&q.value.trim().toLowerCase()!==F.q)q.value=F.q;}' +
  'document.addEventListener("click",function(ev){var t=ev.target;var b=t.closest&&t.closest("[data-f]");if(b){F.cat=b.getAttribute("data-f");F.shown=50;apply();return;}if(t.id==="more"){F.shown+=50;apply();}});' +
  'document.addEventListener("change",function(ev){if(ev.target.id==="svcSel"){F.svc=ev.target.value;F.shown=50;apply();}});' +
  'document.addEventListener("input",function(ev){if(ev.target.id==="userQ"){F.q=ev.target.value.trim().toLowerCase();F.shown=50;apply();}});' +
  'function later(ms){clearTimeout(timer);timer=setTimeout(refresh,ms);}' +
  'function refresh(){if(busy)return;busy=true;var ctl=new AbortController(),to=setTimeout(function(){ctl.abort();},TO);' +
    'fetch(location.pathname+"?_r="+Date.now(),{cache:"no-store",credentials:"same-origin",signal:ctl.signal})' +
    '.then(function(res){if(res.status===401||res.status===403){location.reload();throw new Error("auth");}if(!res.ok)throw new Error("http");return res.text();})' +
    '.then(function(t){var d=new DOMParser().parseFromString(t,"text/html");var n=d.getElementById("app");if(!n)throw new Error("bad");' +
      'var cur=document.getElementById("app");var w0=cur.querySelector(".table-wrap"),st=w0?w0.scrollTop:0,sh=w0?w0.scrollHeight:0,wy=window.scrollY;' +
      'var qa=document.activeElement&&document.activeElement.id==="userQ",qv=qa?document.activeElement.value:null,qs=qa?document.activeElement.selectionStart:0;' +
      'cur.innerHTML=n.innerHTML;cur.setAttribute("data-gen",n.getAttribute("data-gen")||"");lastOk=Date.now();fails=0;apply();' +
      'var w1=cur.querySelector(".table-wrap");if(w1&&st>0)w1.scrollTop=st+(w1.scrollHeight-sh);window.scrollTo(0,wy);' +
      'if(qa){var q2=document.getElementById("userQ");if(q2){q2.value=qv;q2.focus();try{q2.setSelectionRange(qs,qs);}catch(x){}}}tick();later(INT);})' +
    '.catch(function(){fails++;tick();later(fails===1?4000:INT);})' +
    '.then(function(){clearTimeout(to);busy=false;});}' +
  'apply();tick();setInterval(tick,1000);later(INT);' +
'})();</script>';

const html = '<!DOCTYPE html><html lang="es"><head><meta charset="utf-8">' +
